'use strict';
const $=id=>document.getElementById(id),E=BondEngine,fmt=(n,d=2)=>n.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}),pct=n=>fmt(n*100)+'%';
let current;
function read(){let b={face:+$('face').value,coupon:+$('coupon').value/100,yield:+$('yield').value/100,years:+$('years').value,freq:+$('freq').value};let bp=+$('bp').value,h=+$('hold').value,reinvest=$('reinvest').value==='1';if(!Number.isFinite(bp)||Math.abs(bp)>500)throw Error('冲击范围为−500至+500 bp');return {b,bp,h,reinvest};}
function table(id,headers,rows){$(id).innerHTML='<thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody>';}
function plot(b){let data=[];for(let bp=-200;bp<=200;bp+=10)data.push(E.shock(b,bp));let vals=data.flatMap(s=>[s.exact,s.linear,s.quadratic]),lo=Math.min(0,...vals)*100,hi=Math.max(0,...vals)*100,pad=Math.max(1,(hi-lo)*.08);lo-=pad;hi+=pad;let X=x=>65+(x+200)/400*660,Y=y=>280-(y*100-lo)/(hi-lo)*245;
 let svg='';for(let k=0;k<=4;k++){let val=lo+(hi-lo)*k/4,y=Y(val/100);svg+=`<line x1="65" y1="${y}" x2="725" y2="${y}" stroke="#e1e8e5"/><text x="57" y="${y+5}" text-anchor="end" font-size="12" fill="#526872">${val.toFixed(1)}%</text>`;}for(let x=-200;x<=200;x+=100)svg+=`<text x="${X(x)}" y="304" text-anchor="middle" font-size="12" fill="#526872">${x>0?'+':''}${x}</text>`;
 svg+='<text x="398" y="325" text-anchor="middle" font-size="12" fill="#526872">收益率变化（bp）</text><text x="65" y="20" font-size="12" fill="#526872">价格变化率（%）</text>';
 for(let [key,color,dash] of [['linear','#c16f29','5 4'],['quadratic','#675aa4','3 3'],['exact','#087f82','']])svg+=`<path d="${data.map((s,i)=>(i?'L':'M')+X(s.bp).toFixed(2)+' '+Y(s[key]).toFixed(2)).join(' ')}" fill="none" stroke="${color}" stroke-width="2.6" stroke-dasharray="${dash}"/>`;
 $('chart').innerHTML=svg;
}
function render(){try{current=null;$('error').textContent='';let {b,bp,h,reinvest}=read(),a=E.analyze(b),s=E.shock(b,bp),r=E.holding(b,bp,h,reinvest);let list=[['买入价格（元）',fmt(a.price)],['修正久期（年）',fmt(a.modified,3)],['DV01（元）',fmt(a.dv01,4)],['即时价格变动',pct(s.exact)],['持有期总回报',pct(r.total)],['持有期有效年化',pct(r.annual)]];
 $('metrics').innerHTML=list.map(([k,v])=>`<div class="metric"><small>${k}</small><strong>${v}</strong></div>`).join('');
 $('explain').textContent=`收益率从${pct(b.yield)}变为${pct(s.newYield)}。即时重新定价为${fmt(s.price)}元。持有${h}年后，出售价格或到期本金为${fmt(r.terminal)}元，票息合计${fmt(r.couponCash)}元，再投资收益${fmt(r.reinvestment)}元，资本利得/损失${fmt(r.capital)}元。因此持有期总回报为${pct(r.total)}。${r.total<0?'票息收入未能覆盖资本损失。':'在当前情景下，期末总财富高于买入成本。'}`;
 let scenarios=[-200,-100,-50,0,50,100,200].map(x=>E.shock(b,x));table('scenario',['冲击 bp','新YTM','价格 元','精确变动','久期近似','久期+凸性','久期误差 bp','凸性误差 bp'],scenarios.map(s=>[s.bp,pct(s.newYield),fmt(s.price),pct(s.exact),pct(s.linear),pct(s.quadratic),fmt(s.errorLinear),fmt(s.errorQuadratic)]));table('cashflows',['期数','时间 年','现金流 元','现值 元','现值权重'],a.rows.map(x=>[x.period,fmt(x.year),fmt(x.cashflow),fmt(x.pv),pct(x.weight)]));plot(b);current={b,bp,h,reinvest,a,s,r,scenarios};
 }catch(err){$('error').textContent=err.message;$('metrics').innerHTML='';$('explain').textContent='请修正输入后重新计算。';$('chart').innerHTML='';$('scenario').innerHTML='';$('cashflows').innerHTML='';}}
$('form').addEventListener('submit',e=>{e.preventDefault();render();});
for(let btn of document.querySelectorAll('[data-preset]'))btn.onclick=()=>{const p={long:[2,2,10,1],short:[2,2,2,1],zero:[0,2,10,1]}[btn.dataset.preset];['coupon','yield','years','freq'].forEach((id,i)=>$(id).value=p[i]);$('face').value=1000;$('bp').value=100;$('hold').value=1;$('reinvest').value=0;render();};
$('export').onclick=()=>{if(!current)return;const {b,bp,h,reinvest,a,s,r,scenarios}=current;let rows=[['Bond Risk Lab v0.1','教学情景'],['generated_at',new Date().toISOString()],['face',b.face],['coupon_decimal',b.coupon],['yield_nominal_decimal',b.yield],['years',b.years],['frequency',b.freq],['shock_bp',bp],['holding_years',h],['coupon_reinvestment',reinvest],['price',a.price],['macaulay_years',a.macaulay],['modified_years',a.modified],['convexity_years_squared',a.convexity],['dv01_yuan',a.dv01],['holding_total_return_decimal',r.total],['holding_effective_annual_return_decimal',r.annual],[],['shock_bp','new_yield_decimal','price','exact_return_decimal','duration_approx_decimal','convexity_approx_decimal','duration_error_bp','convexity_error_bp'],...scenarios.map(x=>[x.bp,x.newYield,x.price,x.exact,x.linear,x.quadratic,x.errorLinear,x.errorQuadratic]),[],['period','time_years','cashflow_yuan','pv_yuan','pv_weight'],...a.rows.map(x=>[x.period,x.year,x.cashflow,x.pv,x.weight])];let csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download='bond-risk-scenario.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('save').onclick=()=>{try{if(!current)throw Error('请先完成一次有效计算');localStorage.setItem('bond-risk-lab-v01',JSON.stringify(read()));$('status').textContent='已将本组参数保存到当前浏览器。';}catch(e){$('status').textContent='保存失败：'+e.message;}};
$('restore').onclick=()=>{try{let x=JSON.parse(localStorage.getItem('bond-risk-lab-v01'));if(!x)throw Error('还没有保存过参数');for(let id of ['face','years','freq'])$(id).value=x.b[id];$('coupon').value=x.b.coupon*100;$('yield').value=x.b.yield*100;$('bp').value=x.bp;$('hold').value=x.h;$('reinvest').value=x.reinvest?'1':'0';render();$('status').textContent='已恢复上次保存的参数。';}catch(e){$('status').textContent='恢复失败：'+e.message;}};
render();
